// The chrome's and the SDK's shared dialog mechanics.
//
// THIS FILE IS NOT LOADED AT RUNTIME. It is the SOURCE OF TRUTH for a region
// vendored verbatim into both bundles by `python scripts/sync_overlay.py`:
//
//   src/workpeg/ui/runtime/scaffold.js        (the out-of-band chrome)
//   src/workpeg/ui/runtime/workpeg-runtime.js (frozen into every app's dist)
//
// Edit HERE, then run the sync script. A pytest drift guard fails the build if
// a vendored copy stops matching this file.
//
// WHY VENDORED RATHER THAN SHARED AT RUNTIME. The two bundles cannot call each
// other. scaffold.js is published out of band and runs against arbitrarily old
// runtimes, so it may never hard-depend on a new `Workpeg.*` helper; and the
// runtime renders a Modal long before scaffold.js is fetched (it is injected
// lazily on the first Scaffold mount, and an app with no Scaffold never fetches
// it at all). So the implementation has to be present synchronously in BOTH —
// duplicated bytes from one source. Splicing at build time was considered and
// rejected: the CI publish jobs minify these sources directly without going
// through build.py, so a build-time splice would ship a CDN chrome missing this
// code and fall back silently — the exact staleness the publish canary exists
// to catch.
//
// This file is a BARE FUNCTION-BODY FRAGMENT — no IIFE of its own — so the
// vendored copy sits lexically inside its host's closure. Every identifier is
// prefixed `wpo` so it cannot collide with a host's own helpers.
//
// It owns MECHANICS ONLY and ships no CSS: the two bundles' stylesheets have
// irreconcilable delivery models (pegment.css is frozen per app, the chrome's
// STYLES string rides the CDN), so each host keeps its own look and passes its
// own class names in.

// ── the coordinator ────────────────────────────────────────────────────────
// Three things are page-level and cannot live in a per-surface closure: which
// surface owns Escape, how deep the stack is, and how many surfaces hold the
// scroll lock. Both bundles share ONE of these via a global.
//
// FIRST-WINS, deliberately: it holds live state (the claim stack, the lock
// depth), so a later bundle replacing it would strand every existing claim.
// Mechanically that means oldest-wins — index.html loads the runtime
// synchronously before the chrome is injected — so the contract below is
// frozen at v1 and callers must never gate on `v`.
function wpoCoord() {
  var C = window.WorkpegOverlay;
  if (C) return C;
  var claims = [];          // LIFO; the newest owns Escape
  var surfaces = [];        // open surfaces, oldest first
  var lock = { depth: 0, prevOverflow: "", prevBehavior: "" };
  var bound = false;
  C = window.WorkpegOverlay = {
    v: 1,
    // Escape runs the NEWEST claim and stops there, so one keystroke closes
    // exactly one surface. Returns a release function; releasing is idempotent.
    claimEscape: function (fn) {
      var claim = { fn: fn };
      claims.push(claim);
      if (!bound && typeof document !== "undefined") {
        bound = true;
        document.addEventListener("keydown", function (e) {
          if (e.key !== "Escape" || !claims.length) return;
          var top = claims[claims.length - 1];
          // Feature-detected: test harnesses dispatch bare {key} objects.
          if (e.stopPropagation) e.stopPropagation();
          if (e.preventDefault) e.preventDefault();
          top.fn();
        }, true);
      }
      return function () {
        var i = claims.indexOf(claim);
        if (i !== -1) claims.splice(i, 1);
      };
    },
    push: function (root) {
      surfaces.push(root);
      return function () {
        var i = surfaces.indexOf(root);
        if (i !== -1) surfaces.splice(i, 1);
      };
    },
    depth: function () { return surfaces.length; },
    // Refcounted, so closing one of two stacked surfaces does not hand the
    // page back its scrollbar while the other is still open.
    lock: function () {
      var held = true;
      if (lock.depth === 0) {
        try {
          var s = document.body.style;
          lock.prevOverflow = s.overflow;
          lock.prevBehavior = s.overscrollBehavior;
          s.overflow = "hidden";
          s.overscrollBehavior = "contain";
        } catch (e) { /* no body */ }
      }
      lock.depth++;
      return function () {
        if (!held) return;
        held = false;
        lock.depth--;
        if (lock.depth <= 0) {
          lock.depth = 0;
          try {
            var s2 = document.body.style;
            s2.overflow = lock.prevOverflow;
            s2.overscrollBehavior = lock.prevBehavior;
          } catch (e) { /* no body */ }
        }
      };
    }
  };
  return C;
}

var WPO_FOCUSABLE = "a[href],area[href],input:not([disabled]),"
  + "select:not([disabled]),textarea:not([disabled]),button:not([disabled]),"
  + "iframe,object,embed,[tabindex],[contenteditable]";

function wpoFocusable(card) {
  var out = [];
  try {
    var all = card.querySelectorAll(WPO_FOCUSABLE);
    for (var i = 0; i < all.length; i++) {
      var n = all[i];
      if (n.hidden) continue;
      if (n.getAttribute && n.getAttribute("tabindex") === "-1") continue;
      out.push(n);
    }
  } catch (e) { /* a stub DOM without querySelectorAll */ }
  return out;
}

// ── the surface factory ────────────────────────────────────────────────────
// Builds the overlay scaffolding around a caller-supplied `card` node and
// returns a handle. The caller owns every class name and all content; this
// never receives or writes a string of markup, so the chrome's "no innerHTML"
// invariant holds by construction.
//
// See the header of scaffold.js / the Overlays section of workpeg-runtime.js
// for the option list; the shape is:
//   { card, parent, position, rootClass, scrimClass, frameClass, activeClass,
//     width, size, zIndex, onClose, scrimClose, scrimEvent, escClose,
//     onEscape, lockScroll, trapFocus, initialFocus, restoreFocus, persist,
//     exitMs, role, label, labelledBy, onOpen, onHidden }
function wpoSurface(o) {
  if (typeof document === "undefined" || !document.body) return null;
  o = o || {};
  var exitMs = o.exitMs == null ? 200 : o.exitMs;
  var activeClass = o.activeClass || "is-active";
  var persist = !!o.persist;

  var card = o.card;
  var root = document.createElement("div");
  root.className = o.rootClass || "";
  if (o.size) root.className += " " + (o.rootClass || "") + "--" + o.size;
  if (o.position) root.style.position = o.position;
  if (o.zIndex != null) root.style.zIndex = String(o.zIndex);

  // The scrim is either its own node or the root itself; when it IS the root,
  // a click only dismisses if it landed on the root and not on the card.
  var scrim = null;
  if (o.scrimClass) {
    scrim = document.createElement("div");
    scrim.className = o.scrimClass;
    root.appendChild(scrim);
  }
  var host = root;
  if (o.frameClass) {
    host = document.createElement("div");
    host.className = o.frameClass;
    root.appendChild(host);
  }
  host.appendChild(card);

  if (o.width) card.style.maxWidth = "min(92vw, " + Number(o.width) + "px)";
  card.setAttribute("role", o.role || "dialog");
  card.setAttribute("aria-modal", "true");
  if (o.labelledBy) {
    var lid = typeof o.labelledBy === "string" ? o.labelledBy
      : (o.labelledBy.id || (o.labelledBy.id = "wpo-t"
        + (wpoSurface._n = (wpoSurface._n || 0) + 1)));
    card.setAttribute("aria-labelledby", lid);
  } else if (o.label) {
    card.setAttribute("aria-label", o.label);
  }
  if (card.tabIndex === -1 || card.tabIndex === undefined) card.tabIndex = -1;

  var open = false;
  var timer = null;
  var releaseEsc = null;
  var releaseStack = null;
  var releaseLock = null;
  var restoreTo = null;
  var mounted = false;

  function parentNode() {
    var p = typeof o.parent === "function" ? o.parent() : o.parent;
    return p || document.body;
  }

  function requestClose() {
    if (o.onClose) o.onClose();
    else handle.close();
  }

  function onScrim(e) {
    if (!o.scrimClose) return;
    // With no scrim node the root IS the scrim: ignore clicks that came from
    // inside the card.
    if (!scrim && e.target !== root) return;
    requestClose();
  }

  function onKeydown(e) {
    if (!o.trapFocus || e.key !== "Tab") return;
    var f = wpoFocusable(card);
    if (!f.length) { if (e.preventDefault) e.preventDefault(); return; }
    var first = f[0], last = f[f.length - 1];
    var active = document.activeElement;
    if (e.shiftKey && (active === first || active === card)) {
      if (e.preventDefault) e.preventDefault();
      if (last.focus) last.focus();
    } else if (!e.shiftKey && active === last) {
      if (e.preventDefault) e.preventDefault();
      if (first.focus) first.focus();
    }
  }

  (scrim || root).addEventListener(o.scrimEvent || "click", onScrim);
  if (scrim) {
    card.addEventListener("click", function (e) {
      if (e.stopPropagation) e.stopPropagation();
    });
  }
  root.addEventListener("keydown", onKeydown);

  var handle = {
    root: root,
    card: card,
    isOpen: function () { return open; },
    // Swap the dialog's content without tearing the surface down — the SDK
    // rebuilds its card on every render, and re-creating the surface would
    // restart the entry animation and drop focus.
    setCard: function (next) {
      if (!next || next === card) return;
      if (card.parentNode) card.parentNode.replaceChild(next, card);
      card = handle.card = next;
      if (o.width) card.style.maxWidth = "min(92vw, " + Number(o.width) + "px)";
      card.setAttribute("role", o.role || "dialog");
      card.setAttribute("aria-modal", "true");
      if (card.tabIndex === -1 || card.tabIndex === undefined) {
        card.tabIndex = -1;
      }
      if (scrim) {
        card.addEventListener("click", function (e) {
          if (e.stopPropagation) e.stopPropagation();
        });
      }
    },
    open: function () {
      if (timer) { clearTimeout(timer); timer = null; }   // reopen mid-exit
      if (open) return;
      open = true;
      var C = wpoCoord();
      try { restoreTo = document.activeElement; } catch (e) { restoreTo = null; }
      if (!mounted || !persist) {
        parentNode().appendChild(root);
        mounted = true;
      }
      root.hidden = false;
      if (o.escClose !== false) {
        releaseEsc = C.claimEscape(o.onEscape || requestClose);
      }
      releaseStack = C.push(root);
      if (o.lockScroll !== false) releaseLock = C.lock();
      if (o.onOpen) o.onOpen(handle);
      var lift = function () { root.classList.add(activeClass); };
      if (typeof requestAnimationFrame === "function") {
        requestAnimationFrame(lift);
      } else { lift(); }
      var target = typeof o.initialFocus === "function"
        ? o.initialFocus() : o.initialFocus;
      try { (target || card).focus(); } catch (e) { /* stub DOM */ }
    },
    close: function () {
      if (!open) return;
      open = false;
      if (releaseEsc) { releaseEsc(); releaseEsc = null; }
      if (releaseStack) { releaseStack(); releaseStack = null; }
      if (releaseLock) { releaseLock(); releaseLock = null; }
      root.classList.remove(activeClass);
      if (timer) clearTimeout(timer);
      timer = setTimeout(function () {
        timer = null;
        if (persist) { root.hidden = true; }
        else if (root.parentNode) {
          root.parentNode.removeChild(root);
          mounted = false;
        }
        if (o.onHidden) o.onHidden(handle);
      }, exitMs);
      if (o.restoreFocus !== false && restoreTo && restoreTo.focus) {
        try { restoreTo.focus(); } catch (e) { /* gone from the DOM */ }
      }
      restoreTo = null;
    },
    // Tear down now, with no animation — used when a whole app unmounts.
    destroy: function () {
      open = false;
      if (timer) { clearTimeout(timer); timer = null; }
      if (releaseEsc) { releaseEsc(); releaseEsc = null; }
      if (releaseStack) { releaseStack(); releaseStack = null; }
      if (releaseLock) { releaseLock(); releaseLock = null; }
      if (root.parentNode) root.parentNode.removeChild(root);
      mounted = false;
    }
  };

  if (persist) root.hidden = true;
  return handle;
}
